from pathlib import Path
import json
P=Path(__file__).parent;D=json.loads((P/'depth_audit.json').read_text());S=json.loads((P/'depth_supplement.json').read_text())
lines=['# 独立只读 depth-head 审计','', '## 范围和方法','', '- 服务器 `ssh -n animsrv`；仅执行 `/data/video2rig/.venv/bin/python` + NumPy CPU 数组运算。未加载模型、未训练、未运行GPU、未改核心或部署；远端新增文件仅 `/tmp/v2r_depth_*`。','- 统计两个项目所有19份 reading 快照；同源输出重复不是独立测试集，exam/exam_temporal也不是两个独立考试。','- GT严格取各项目 `exam/frames/motion_gt.json` 的各视图 uvz[:,2]，每帧每视图全28点均值归零后除 rig.size=2.6133360266685486。不拟合尺度、不翻转深度符号。正z是更远。','- 镜像字段互反且有效，8对。ankle.L/R索引22/26；不是骨骼索引18/21。','- 全阈值曲线预先固定为 0/.01/.02/.04/.08 normalized size，保留条件严格 |pred(L)-pred(R)|>阈值。coverage分母是该子集全部样本；error为保留样本误序率。相邻帧相关，不把样本数当独立证据。','- 真实片无GT；只报告深度时间变化、相邻排序翻转和同双视角 triang 排序冲突。triang由同一UV及相机推得，是相关一致性参照，绝不是GT。','', '## 保存对齐检查：temporal已正确重排，legacy未修','', '- 从 saved uv_raw 到 uv 的逐槽匹配恢复交换映射，所有快照未知映射数=0；不凭文件名推定对齐。','- lizard exam：frame30（0-based），side，后腿整链8槽/4mirror对交换。exam_temporal.depth严格等于permutation(exam.depth)，最大差0。xiyi_temporal相对xiyi也严格符合24槽交换（frame78/79 side，89 front）。','- xiyi2、xiyi3及clean项目所有目标无swap，legacy/temporal原始depth逐元素相同；这是排除重排混杂的控制。','- 当前源pipeline temporal分支115–118重排dep和quality；legacy120只交换uv/conf。legacy继续存在潜在错配，不应拿其交换样本直接比较。','', '### frame30 side：UV交换与深度身份并不总是同一问题','', '- 已对齐temporal在这8槽的GT深度MAE=.174650，legacy raw depth=.013836；4个深度pair排序由对变错。不能为了GT分数撤回正确的slot重排。','- 详细UV核对显示：hip.L/R误差由1.27/3.54px增至8.58/10.05px；knee.L/R 7.64/1.65→10.29/7.45px；ankle.L 3.49→2.76px，ankle.R 36.98→37.01px；tip则40.60/36.94→1.62/2.41px。整链交换改善了tips，却损伤proximal身份；深度head仍保留原本正确的左右深度次序。更准确结论是“整链UV identity决策与depth head身份耦合不一致”，不是所有UV交换都错。','- temporal该ankle两端conf约.840/.813，但conf_fit降至.237/.277：原始conf不能保证深度排序；融合可靠性可降低影响。','', '## GT点深度MAE','', '|run|all n=8400|可见 n=7399|单视图遮挡 n=1001|该点双视图vis=0 n=210视图槽|','|---|---:|---:|---:|---:|']
for p,n in [('lizard','exam'),('lizard','exam_temporal'),('lizard_clean','exam')]:
 r=D['projects'][p]['runs'][n];m=r['GT_point_MAE'];lines.append('|'+p+'/'+n+'|'+'|'.join(f"{m[k]['mean']:.6f}" for k in ['all','visible_same_view','occluded_same_view','keypoint_both_views_occluded'])+'|')
lines+=['','双视图不可见点共有105个frame-keypoint（两视图槽计210）。不同模型对不可见点的MAE没有一致改善。','', '## GT镜像排序：accuracy / coverage / wrong-kept','']
def table(rows):
 lines.extend(['|阈值|accuracy|coverage|wrong/kept|pair差MAE|','|---:|---:|---:|---:|---:|'])
 for x in rows:lines.append(f"|{x['threshold']:.2f}|{100*x['accuracy']:.2f}%|{100*x['coverage']:.2f}%|{x['wrong']}/{x['n']}|{x['pair_diff_MAE']:.5f}|")
for p,n in [('lizard','exam_temporal'),('lizard_clean','exam')]:
 r=D['projects'][p]['runs'][n];lines+=['### '+p+'/'+n+'：全部8对，2400 pair-view-frame',''];table(r['GT_pair_order']['all']);lines+=['','### '+p+'/'+n+'：ankle.L/R，300 pair-view-frame',''];table(r['GT_ankle_order']['all']);lines+=['','### '+p+'/'+n+'：同一视图mirror两端都vis=0，39样本',''];table(r['GT_pair_order']['pair_both_occluded_same_view']);lines+=['','### '+p+'/'+n+'：上述真实双遮挡ankle，9样本',''];table(r['GT_ankle_order']['pair_both_occluded_same_view']);lines+=['','### '+p+'/'+n+'：pair至少一端在两个视图都vis=0',''];table(r['GT_pair_order']['pair_has_keypoint_occluded_both_views']);lines+=['','### '+p+'/'+n+'：ankle至少一端在两个视图都vis=0',''];table(r['GT_ankle_order']['pair_has_keypoint_occluded_both_views']);lines+=['']
lines+=['“两mirror端同一视图都不可见”和“一个keypoint两个视图都不可见”是不同子集，本报告两者均列。四个vis全0子集只有1个frame-pair/2个view样本，也保存在JSON，不用conf低替代实际遮挡。双遮挡n很小，1/1、2/2甚至14/14均不能证明安全。','', '### confidence并非depth排序置信度','', '- lizard exam_temporal原始pair min-conf>=.5保留2290/2400，th0 accuracy92.49%；conf_fit>=.5保留852/2400，th0 accuracy91.08%。两种confidence都不是已校准的排序概率。','- conf_fit>=.5且margin>.04为22/651错，coverage相对全体仅27.13%；>.08为6/442错，coverage18.42%。这些是描述性曲线，不以测试后效果选择预设。','- 不同solver的conf_fit尺度不同：clean exam是legacy，不能用同一数值门槛当跨solver校准。','', '## 各视图ankle：不应被合并均值掩盖','', '|run/view|th0 acc|th.04 acc / coverage|th.08 acc / coverage|','|---|---:|---:|---:|']
for p,n in [('lizard','exam_temporal'),('lizard_clean','exam')]:
 for v,rr in D['projects'][p]['runs'][n]['GT_ankle_order']['by_view'].items():lines.append(f"|{p}/{n}/{v}|{rr[0]['accuracy']:.2%}|{rr[3]['accuracy']:.2%} / {rr[3]['coverage']:.2%}|{rr[4]['accuracy']:.2%} / {rr[4]['coverage']:.2%}|")
lines+=['','## 真实片：只报告稳定性和triang冲突（NOT accuracy）','', '以下为threshold=.04（.08括号内）。冲突分母为保留样本；flip分母是相邻两帧都过阈值的相邻对。高稳定可以稳定地错；高triang冲突也不说明depth一定错。','', '|run/view/group|coverage .04 (.08)|triang冲突 .04 (.08)|相邻排序flip .04 (.08)|pair diff Δt绝对值均值 / p90|','|---|---:|---:|---:|---:|']
for p in ['lizard','lizard_clean']:
 for n in ['xiyi_temporal','xiyi2_temporal_web','xiyi3_temporal','xiyi3_clean_temporal']:
  if n not in S[p]:continue
  # avoid exact clean duplicates
  if p=='lizard_clean' and n=='xiyi3_temporal':continue
  for v,d in S[p][n].items():
   for label,q in d.items():
    a,b=q['rows'][3:5];pct=lambda x:f'{x:.2%}' if x is not None else 'n/a';fmt=lambda k:pct(a[k])+' ('+pct(b[k])+')'
    lines.append(f"|{p}/{n}/{v}/{label}|{fmt('coverage')}|{fmt('tri_conflict')}|{fmt('flip_rate')}|{q['step_mean']:.5f} / {q['step_p90']:.5f}|")
lines+=['','完整0/.01/.02/.04/.08曲线、每个镜像pair、conf/conf_fit筛选、triang强间距对照及时间差分见JSON。lizard xiyi3 front ankle在.04为47/48 triang冲突、37个相邻保留对0次flip；clean为15/20冲突、17个相邻对0flip。但是这些保留样本的triang |diff|全部<=.02size，不能称97.92%深度错误；这是近等深几何下的稳定符号偏置/排序冲突。xiyi2 front ankle同样没有任何triang |diff|>.02的保留样本。真实片front经常接近左右等深；建议结合相机朝向/triang间距查看冲突，不能把“相同front/side符号”当跨视图一致性（两相机深度轴不同）。','', '## 建议：不把测试后最佳阈值当预设','', '1. **depth只做软排序证据，不自动驱动硬swap，更不用于双遮挡关节的硬重建。** MAE约.023–.024size，但ankle误序更高；真实片与同UV三角测量冲突明显且无GT。','2. 若必须设计未验证的工程初始门槛，可预先登记 **|Δpred|<=.04size abstain；>.04仅弱软约束；>.08只标记strong候选，仍需conf_fit/几何/连续性共同同意**。这里的.04/.08是可解释的4%/8%体尺margin级别，不声称由本考试优化而得，也不声称达到某个错误上限。后续应在新held-out动作/新遮挡采样验证，才能变为正式默认。','3. 尤其ankle.L/R真实双遮挡先保持abstain。当前lizard在.04仅2/4正确，.08仅1/1；clean .04为5/5、.08为2/2，证据远不足。更高阈值不能从此小样本证明解决遮挡。','4. 保留temporal的正确slot对齐；未来核心变更候选（本次未改）：legacy统一permutation、持久化raw/aligned depth及permutation，区分UV整链换标与depth身份，加入depth-vs-swap冲突标记。不要用被错误整链交换的高conf深度强迫solver。','5. 需要校准coverage/error时，以独立片段为统计单位；不能将150帧8对×2视图当2400个独立样本，不能对真实片用triang选择“最佳准确率阈值”。','', '## 产物','', '- 本地 `work/analyze/depth/audit_depth.py`、`supplement_depth.py`：可复现只读脚本。','- 本地 `work/analyze/depth/depth_audit.json`、`depth_supplement.json`：完整数值；远端同内容 `/tmp/v2r_depth_audit.json`、`/tmp/v2r_depth_supplement.json`。','- source_*.py 为本次远端源码只读快照（非部署文件）。','']
(P/'depth_report.md').write_text('\n'.join(lines),encoding='utf-8');print('\n'.join(lines))
